/**
 * @file getContrastRatio - Calculate WCAG contrast ratio
 * @module @dsai-io/react/utils/color
 *
 * Enterprise-grade contrast ratio calculator with:
 * - WCAG 2.1 compliant formula
 * - RGB color support
 * - Range validation
 * - Optional precision control for display vs computation
 */

import { getRelativeLuminance } from './getRelativeLuminance';

/**
 * Options for contrast ratio calculation
 */
export interface ContrastRatioOptions {
  /**
   * Number of decimal places to round the result to.
   * Use `null` or `undefined` for full precision (recommended for WCAG comparison).
   * Use `2` for display purposes.
   * @default undefined (full precision)
   */
  precision?: number | null;
}

/**
 * Calculate contrast ratio between two RGB colors per WCAG 2.1
 * Formula: (L1 + 0.05) / (L2 + 0.05)
 * Where L1 is lighter color, L2 is darker color
 *
 * @param rgb1 - First color [r, g, b] (0-255 each)
 * @param rgb2 - Second color [r, g, b] (0-255 each)
 * @param options - Optional configuration
 * @returns Contrast ratio (1-21)
 *
 * @remarks
 * By default, returns full precision for accurate WCAG compliance checking.
 * Use `{ precision: 2 }` when displaying to users for readability.
 *
 * @example
 * ```tsx
 * // Black on white
 * getContrastRatio([0, 0, 0], [255, 255, 255]); // 21
 *
 * // White on white
 * getContrastRatio([255, 255, 255], [255, 255, 255]); // 1
 *
 * // Dark gray on light gray
 * getContrastRatio([68, 68, 68], [238, 238, 238]); // ~12.6
 *
 * // For display (rounded)
 * getContrastRatio([0, 0, 255], [255, 255, 255], { precision: 2 }); // 8.59
 * ```
 */
export function getContrastRatio(
  rgb1: readonly [number, number, number],
  rgb2: readonly [number, number, number],
  options: ContrastRatioOptions = {}
): number {
  const { precision } = options;

  // Validate inputs
  if (!Array.isArray(rgb1) || rgb1.length !== 3) {
    console.warn('[getContrastRatio] First color must be [r, g, b] array');
    return 1;
  }

  if (!Array.isArray(rgb2) || rgb2.length !== 3) {
    console.warn('[getContrastRatio] Second color must be [r, g, b] array');
    return 1;
  }

  // Calculate relative luminance for both colors
  const l1 = getRelativeLuminance(rgb1[0], rgb1[1], rgb1[2]);
  const l2 = getRelativeLuminance(rgb2[0], rgb2[1], rgb2[2]);

  // Determine lighter and darker
  const lighter = Math.max(l1, l2);
  const darker = Math.min(l1, l2);

  // Calculate contrast ratio
  const ratio = (lighter + 0.05) / (darker + 0.05);

  // Apply precision if specified
  if (typeof precision === 'number' && precision >= 0) {
    const factor = 10 ** precision;
    return Math.round(ratio * factor) / factor;
  }

  // Return full precision for accurate WCAG comparison
  return ratio;
}

/**
 * @file getDarkerShade - Generate darker color shade
 * @module @dsai-io/react/utils/color
 *
 * Enterprise-grade color darkening with:
 * - HSL color space manipulation
 * - Percentage-based darkening
 * - Boundary protection
 * - Hex input/output
 */

import { hexToRgb } from './hexToRgb';
import { hslToHex } from './hslToHex';
import { rgbToHsl } from './rgbToHsl';

/**
 * Generate a darker shade of a color
 *
 * @param hex - Base color in hex format
 * @param percent - Percentage to darken (0-100)
 * @returns Darker hex color or original if invalid
 *
 * @example
 * ```tsx
 * // Darken blue by 20%
 * getDarkerShade('#3B82F6', 20); // '#2563EB'
 *
 * // Darken light gray by 30%
 * getDarkerShade('#CCCCCC', 30); // '#8A8A8A'
 *
 * // Already very dark - minimal change
 * getDarkerShade('#111111', 10); // '#0A0A0A'
 *
 * // Component usage - active state
 * const buttonBg = '#3B82F6';
 * const buttonActive = getDarkerShade(buttonBg, 15);
 *
 * <button
 *   style={{
 *     backgroundColor: buttonBg,
 *     ':active': { backgroundColor: buttonActive }
 *   }}
 * >
 *   Click me
 * </button>
 *
 * // Generate palette (dark to light)
 * const base = '#10B981'; // green-500
 * const palette = [40, 30, 20, 10, 0].map(p =>
 *   p > 0 ? getDarkerShade(base, p) : base
 * );
 * ```
 */
export function getDarkerShade(hex: string, percent: number): string {
  // Validate percent
  if (percent < 0 || percent > 100) {
    console.warn('[getDarkerShade] Percent must be in range 0-100');
    percent = Math.max(0, Math.min(100, percent));
  }

  // Convert hex to RGB
  const rgb = hexToRgb(hex);
  if (!rgb) {
    console.warn('[getDarkerShade] Invalid hex color, returning original:', hex);
    return hex;
  }

  // Convert RGB to HSL
  const [h, s, l] = rgbToHsl(rgb[0], rgb[1], rgb[2]);

  // Calculate new lightness
  // Decrease lightness by percentage of space to black
  const decrease = (l * percent) / 100;
  const newL = Math.max(0, l - decrease);

  // Convert back to hex
  return hslToHex(h, s, newL);
}

/**
 * @file getLighterShade - Generate lighter color shade
 * @module @dsai-io/react/utils/color
 *
 * Enterprise-grade color lightening with:
 * - HSL color space manipulation
 * - Percentage-based lightening
 * - Boundary protection
 * - Hex input/output
 */

import { hexToRgb } from './hexToRgb';
import { hslToHex } from './hslToHex';
import { rgbToHsl } from './rgbToHsl';

/**
 * Generate a lighter shade of a color
 *
 * @param hex - Base color in hex format
 * @param percent - Percentage to lighten (0-100)
 * @returns Lighter hex color or original if invalid
 *
 * @example
 * ```tsx
 * // Lighten blue by 20%
 * getLighterShade('#3B82F6', 20); // '#6BA4F8'
 *
 * // Lighten dark gray by 30%
 * getLighterShade('#333333', 30); // '#666666'
 *
 * // Already very light - minimal change
 * getLighterShade('#EEEEEE', 10); // '#F5F5F5'
 *
 * // Component usage - hover state
 * const buttonBg = '#3B82F6';
 * const buttonHover = getLighterShade(buttonBg, 10);
 *
 * <button
 *   style={{
 *     backgroundColor: buttonBg,
 *     ':hover': { backgroundColor: buttonHover }
 *   }}
 * >
 *   Click me
 * </button>
 *
 * // Generate palette
 * const base = '#10B981'; // green-500
 * const palette = [10, 20, 30, 40].map(p =>
 *   getLighterShade(base, p)
 * );
 * ```
 */
export function getLighterShade(hex: string, percent: number): string {
  // Validate percent
  if (percent < 0 || percent > 100) {
    console.warn('[getLighterShade] Percent must be in range 0-100');
    percent = Math.max(0, Math.min(100, percent));
  }

  // Convert hex to RGB
  const rgb = hexToRgb(hex);
  if (!rgb) {
    console.warn('[getLighterShade] Invalid hex color, returning original:', hex);
    return hex;
  }

  // Convert RGB to HSL
  const [h, s, l] = rgbToHsl(rgb[0], rgb[1], rgb[2]);

  // Calculate new lightness
  // Increase lightness by percentage of remaining space to white
  const remainingSpace = 100 - l;
  const increase = (remainingSpace * percent) / 100;
  const newL = Math.min(100, l + increase);

  // Convert back to hex
  return hslToHex(h, s, newL);
}

/**
 * @file getRelativeLuminance - Calculate relative luminance per WCAG
 * @module @dsai-io/react/utils/color
 *
 * Enterprise-grade relative luminance calculator with:
 * - WCAG 2.1 compliant formula
 * - RGB color space conversion
 * - Linearization with gamma correction
 * - Input validation
 */

/**
 * Calculate relative luminance of an RGB color per WCAG 2.1
 * Formula: L = 0.2126 * R + 0.7152 * G + 0.0722 * B
 * Where R, G, B are linearized sRGB values
 *
 * @param r - Red channel (0-255)
 * @param g - Green channel (0-255)
 * @param b - Blue channel (0-255)
 * @returns Relative luminance (0-1)
 *
 * @example
 * ```tsx
 * // Pure white
 * getRelativeLuminance(255, 255, 255); // 1.0
 *
 * // Pure black
 * getRelativeLuminance(0, 0, 0); // 0.0
 *
 * // Medium gray
 * getRelativeLuminance(128, 128, 128); // ~0.215
 *
 * // Blue
 * getRelativeLuminance(0, 0, 255); // ~0.0722
 * ```
 */
export function getRelativeLuminance(r: number, g: number, b: number): number {
  // Validate inputs
  if (r < 0 || r > 255 || g < 0 || g > 255 || b < 0 || b > 255) {
    console.warn('[getRelativeLuminance] RGB values must be in range 0-255');
    // Clamp values
    r = Math.max(0, Math.min(255, r));
    g = Math.max(0, Math.min(255, g));
    b = Math.max(0, Math.min(255, b));
  }

  // Convert to 0-1 range
  const rsRGB = r / 255;
  const gsRGB = g / 255;
  const bsRGB = b / 255;

  // Linearize sRGB values (gamma correction)
  const rLinear = linearize(rsRGB);
  const gLinear = linearize(gsRGB);
  const bLinear = linearize(bsRGB);

  // Calculate relative luminance using WCAG coefficients
  return 0.2126 * rLinear + 0.7152 * gLinear + 0.0722 * bLinear;
}

/**
 * Linearize sRGB channel value (inverse gamma correction)
 *
 * @param channel - sRGB channel value (0-1)
 * @returns Linearized value (0-1)
 */
function linearize(channel: number): number {
  // WCAG formula for linearization
  if (channel <= 0.03928) {
    return channel / 12.92;
  }
  return ((channel + 0.055) / 1.055) ** 2.4;
}

/**
 * @file hexToRgb - Convert hex color to RGB
 * @module @dsai-io/react/utils/color
 *
 * Enterprise-grade hex to RGB converter with:
 * - 3-digit and 6-digit hex support
 * - Hash prefix handling
 * - Input validation
 * - Type-safe output
 */

/**
 * Convert hex color string to RGB tuple
 *
 * @param hex - Hex color (#RGB or #RRGGBB)
 * @returns RGB tuple [r, g, b] or null if invalid
 *
 * @example
 * ```tsx
 * // 6-digit hex
 * hexToRgb('#FF5733'); // [255, 87, 51]
 *
 * // 3-digit hex (shorthand)
 * hexToRgb('#F00'); // [255, 0, 0]
 *
 * // Without hash
 * hexToRgb('00FF00'); // [0, 255, 0]
 *
 * // Invalid input
 * hexToRgb('#GGG'); // null
 * hexToRgb('invalid'); // null
 *
 * // Component usage
 * const colorHex = '#3B82F6'; // blue-500
 * const rgb = hexToRgb(colorHex);
 * if (rgb) {
 *   const [r, g, b] = rgb;
 *   console.log(`RGB: ${r}, ${g}, ${b}`);
 * }
 * ```
 */
export function hexToRgb(hex: string): readonly [number, number, number] | null {
  // Validate input
  if (typeof hex !== 'string' || hex.trim() === '') {
    console.warn('[hexToRgb] Invalid hex color: must be non-empty string');
    return null;
  }

  // Remove hash if present
  let cleanHex = hex.trim();
  if (cleanHex.startsWith('#')) {
    cleanHex = cleanHex.slice(1);
  }

  // Validate hex format
  if (!/^[0-9A-Fa-f]{3}$|^[0-9A-Fa-f]{6}$/.test(cleanHex)) {
    console.warn('[hexToRgb] Invalid hex color format:', hex);
    return null;
  }

  // Expand 3-digit hex to 6-digit
  if (cleanHex.length === 3) {
    cleanHex = cleanHex
      .split('')
      .map((char) => char + char)
      .join('');
  }

  // Parse RGB values
  const r = Number.parseInt(cleanHex.slice(0, 2), 16);
  const g = Number.parseInt(cleanHex.slice(2, 4), 16);
  const b = Number.parseInt(cleanHex.slice(4, 6), 16);

  // Validate parsed values (should always be valid if regex passed)
  if (Number.isNaN(r) || Number.isNaN(g) || Number.isNaN(b)) {
    console.warn('[hexToRgb] Failed to parse hex color:', hex);
    return null;
  }

  return [r, g, b] as const;
}

/**
 * @file hslToHex - Convert HSL to hex color
 * @module @dsai-io/react/utils/color
 *
 * Enterprise-grade HSL to hex converter with:
 * - Accurate color space conversion
 * - Hue, saturation, lightness handling
 * - Input validation and clamping
 * - Uppercase hex output
 */

/**
 * Convert HSL color to hex string
 *
 * @param h - Hue (0-360 degrees)
 * @param s - Saturation (0-100 percent)
 * @param l - Lightness (0-100 percent)
 * @returns Hex color string (#RRGGBB)
 *
 * @example
 * ```tsx
 * // Pure red
 * hslToHex(0, 100, 50); // '#FF0000'
 *
 * // Pure green
 * hslToHex(120, 100, 50); // '#00FF00'
 *
 * // Pure blue
 * hslToHex(240, 100, 50); // '#0000FF'
 *
 * // Gray
 * hslToHex(0, 0, 50); // '#808080'
 *
 * // Component usage - generate color palette
 * const baseHue = 210; // blue
 * const colors = [30, 50, 70].map(lightness =>
 *   hslToHex(baseHue, 80, lightness)
 * );
 * // ['#266ACC', '#66A3E6', '#99C2F0']
 * ```
 */
export function hslToHex(h: number, s: number, l: number): string {
  // Validate and clamp inputs
  if (h < 0 || h > 360) {
    console.warn('[hslToHex] Hue must be in range 0-360');
    h = ((h % 360) + 360) % 360; // Wrap around
  }

  if (s < 0 || s > 100) {
    console.warn('[hslToHex] Saturation must be in range 0-100');
    s = Math.max(0, Math.min(100, s));
  }

  if (l < 0 || l > 100) {
    console.warn('[hslToHex] Lightness must be in range 0-100');
    l = Math.max(0, Math.min(100, l));
  }

  // Convert to 0-1 range
  const sNorm = s / 100;
  const lNorm = l / 100;

  // Calculate chroma
  const c = (1 - Math.abs(2 * lNorm - 1)) * sNorm;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = lNorm - c / 2;

  // Determine RGB based on hue
  let r = 0;
  let g = 0;
  let b = 0;

  if (h >= 0 && h < 60) {
    [r, g, b] = [c, x, 0];
  } else if (h >= 60 && h < 120) {
    [r, g, b] = [x, c, 0];
  } else if (h >= 120 && h < 180) {
    [r, g, b] = [0, c, x];
  } else if (h >= 180 && h < 240) {
    [r, g, b] = [0, x, c];
  } else if (h >= 240 && h < 300) {
    [r, g, b] = [x, 0, c];
  } else {
    [r, g, b] = [c, 0, x];
  }

  // Convert to 0-255 range
  const r255 = Math.round((r + m) * 255);
  const g255 = Math.round((g + m) * 255);
  const b255 = Math.round((b + m) * 255);

  // Convert to hex
  const rHex = r255.toString(16).padStart(2, '0').toUpperCase();
  const gHex = g255.toString(16).padStart(2, '0').toUpperCase();
  const bHex = b255.toString(16).padStart(2, '0').toUpperCase();

  return `#${rHex}${gHex}${bHex}`;
}

/**
 * @file Color & Theming utilities
 * @module @dsai-io/react/utils/color
 *
 * Enterprise-grade color manipulation and WCAG compliance utilities including:
 * - WCAG contrast checking (getContrastRatio, meetsWCAG, getRelativeLuminance)
 * - Color space conversions (hexToRgb, rgbToHsl, hslToHex)
 * - Shade generation (getLighterShade, getDarkerShade)
 * - Design token conversion (tokenToCssVar)
 */

// WCAG Compliance
export { getContrastRatio } from './getContrastRatio';
export type { ContrastRatioOptions } from './getContrastRatio';
export { getRelativeLuminance } from './getRelativeLuminance';
export { meetsWCAG } from './meetsWCAG';
export type { TextSize, WCAGLevel, WCAGOptions } from './meetsWCAG';

// Color Space Conversions
export { hexToRgb } from './hexToRgb';
export { hslToHex } from './hslToHex';
export { rgbToHsl } from './rgbToHsl';

// Shade Generation
export { getDarkerShade } from './getDarkerShade';
export { getLighterShade } from './getLighterShade';

// Design Tokens
export { tokenToCssVar } from './tokenToCssVar';
export type { TokenToCssVarOptions } from './tokenToCssVar';

/**
 * @file meetsWCAG - Check WCAG contrast compliance
 * @module @dsai-io/react/utils/color
 *
 * Enterprise-grade WCAG compliance checker with:
 * - AA and AAA level support
 * - Normal and large text modes
 * - Type-safe level checking
 */

import { getContrastRatio } from './getContrastRatio';

/**
 * WCAG conformance levels
 */
export type WCAGLevel = 'AA' | 'AAA';

/**
 * Text size for WCAG calculations
 */
export type TextSize = 'normal' | 'large';

/**
 * Options for WCAG compliance checking
 */
export interface WCAGOptions {
  /** WCAG level to check (AA or AAA) */
  level: WCAGLevel;
  /** Text size (normal: <18pt, large: >=18pt or >=14pt bold) */
  textSize?: TextSize;
}

/**
 * Check if contrast ratio meets WCAG requirements
 *
 * WCAG 2.1 Requirements:
 * - AA Normal: 4.5:1
 * - AA Large: 3:1
 * - AAA Normal: 7:1
 * - AAA Large: 4.5:1
 *
 * @param rgb1 - First color [r, g, b]
 * @param rgb2 - Second color [r, g, b]
 * @param options - WCAG checking options
 * @returns True if meets requirement
 *
 * @example
 * ```tsx
 * const black = [0, 0, 0] as const;
 * const white = [255, 255, 255] as const;
 * const gray = [128, 128, 128] as const;
 *
 * // Black on white - excellent contrast
 * meetsWCAG(black, white, { level: 'AAA' }); // true
 *
 * // Gray on white - may fail AAA for normal text
 * meetsWCAG(gray, white, { level: 'AAA' }); // false
 * meetsWCAG(gray, white, { level: 'AA' }); // true
 *
 * // Large text has lower requirements
 * meetsWCAG(gray, white, { level: 'AAA', textSize: 'large' }); // true
 *
 * // Component usage
 * const buttonBg = [59, 130, 246] as const; // blue-500
 * const buttonText = [255, 255, 255] as const; // white
 *
 * if (!meetsWCAG(buttonText, buttonBg, { level: 'AA' })) {
 *   console.warn('Button text contrast is too low');
 * }
 * ```
 */
export function meetsWCAG(
  rgb1: readonly [number, number, number],
  rgb2: readonly [number, number, number],
  options: WCAGOptions
): boolean {
  const { level, textSize = 'normal' } = options;

  // Validate level
  if (level !== 'AA' && level !== 'AAA') {
    console.warn('[meetsWCAG] Invalid level, must be AA or AAA');
    return false;
  }

  // Calculate contrast ratio
  const ratio = getContrastRatio(rgb1, rgb2);

  // Determine required ratio based on level and text size
  const requiredRatio = getRequiredRatio(level, textSize);

  return ratio >= requiredRatio;
}

/**
 * Get required contrast ratio for WCAG level and text size
 *
 * @param level - WCAG level
 * @param textSize - Text size
 * @returns Required contrast ratio
 */
function getRequiredRatio(level: WCAGLevel, textSize: TextSize): number {
  if (level === 'AAA') {
    return textSize === 'large' ? 4.5 : 7;
  }
  // AA
  return textSize === 'large' ? 3 : 4.5;
}

/**
 * @file rgbToHsl - Convert RGB to HSL color space
 * @module @dsai-io/react/utils/color
 *
 * Enterprise-grade RGB to HSL converter with:
 * - Accurate color space conversion
 * - Hue calculation in degrees
 * - Saturation and lightness as percentages
 * - Input validation
 */

/**
 * HSL color tuple
 */
export type HSL = readonly [number, number, number];

/**
 * Convert RGB color to HSL color space
 *
 * @param r - Red channel (0-255)
 * @param g - Green channel (0-255)
 * @param b - Blue channel (0-255)
 * @returns HSL tuple [h (0-360), s (0-100), l (0-100)]
 *
 * @example
 * ```tsx
 * // Pure red
 * rgbToHsl(255, 0, 0); // [0, 100, 50]
 *
 * // Pure green
 * rgbToHsl(0, 255, 0); // [120, 100, 50]
 *
 * // Pure blue
 * rgbToHsl(0, 0, 255); // [240, 100, 50]
 *
 * // Gray (no saturation)
 * rgbToHsl(128, 128, 128); // [0, 0, 50]
 *
 * // Component usage - adjust lightness
 * const [r, g, b] = [59, 130, 246]; // blue-500
 * const [h, s, l] = rgbToHsl(r, g, b);
 * const lighterL = Math.min(l + 10, 100);
 * console.log(`Lighter: hsl(${h}, ${s}%, ${lighterL}%)`);
 * ```
 */
export function rgbToHsl(r: number, g: number, b: number): HSL {
  // Validate and clamp inputs
  if (r < 0 || r > 255 || g < 0 || g > 255 || b < 0 || b > 255) {
    console.warn('[rgbToHsl] RGB values must be in range 0-255');
    r = Math.max(0, Math.min(255, r));
    g = Math.max(0, Math.min(255, g));
    b = Math.max(0, Math.min(255, b));
  }

  // Convert to 0-1 range
  const rNorm = r / 255;
  const gNorm = g / 255;
  const bNorm = b / 255;

  // Find min and max channel values
  const max = Math.max(rNorm, gNorm, bNorm);
  const min = Math.min(rNorm, gNorm, bNorm);
  const delta = max - min;

  // Calculate lightness (0-1 range)
  const l = (max + min) / 2;

  // Calculate saturation
  let s = 0;
  if (delta !== 0) {
    s = delta / (1 - Math.abs(2 * l - 1));
  }

  // Calculate hue in degrees
  let h = 0;
  if (delta !== 0) {
    if (max === rNorm) {
      h = ((gNorm - bNorm) / delta) % 6;
    } else if (max === gNorm) {
      h = (bNorm - rNorm) / delta + 2;
    } else {
      h = (rNorm - gNorm) / delta + 4;
    }
    h = h * 60;
  }

  // Normalize hue to 0-360
  if (h < 0) {
    h += 360;
  }

  // Return full precision values for accurate roundtrip conversions
  return [h, s * 100, l * 100] as const;
}

/**
 * @file tokenToCssVar - Convert design token to CSS variable
 * @module @dsai-io/react/utils/color
 *
 * Enterprise-grade token to CSS variable converter with:
 * - Dot notation support (colors.primary.500)
 * - Kebab-case conversion
 * - Prefix support
 * - Validation
 */

/**
 * Options for token to CSS variable conversion
 */
export interface TokenToCssVarOptions {
  /** Prefix for CSS variable (default: '') */
  prefix?: string;
  /** Whether to include --var() wrapper (default: false) */
  withVar?: boolean;
}

/**
 * Convert design token path to CSS variable name
 *
 * @param token - Design token path (e.g., 'colors.primary.500')
 * @param options - Conversion options
 * @returns CSS variable name (e.g., '--colors-primary-500' or 'var(--colors-primary-500)')
 *
 * @example
 * ```tsx
 * // Basic conversion
 * tokenToCssVar('colors.primary.500'); // '--colors-primary-500'
 *
 * // With prefix
 * tokenToCssVar('primary.500', { prefix: 'color' }); // '--color-primary-500'
 *
 * // With var() wrapper
 * tokenToCssVar('spacing.xl', { withVar: true }); // 'var(--spacing-xl)'
 *
 * // Both prefix and var()
 * tokenToCssVar('blue.500', {
 *   prefix: 'color',
 *   withVar: true
 * }); // 'var(--color-blue-500)'
 *
 * // Component usage
 * const theme = {
 *   primary: 'colors.primary.500',
 *   secondary: 'colors.secondary.500'
 * };
 *
 * <div
 *   style={{
 *     color: tokenToCssVar(theme.primary, { withVar: true }),
 *     backgroundColor: tokenToCssVar(theme.secondary, { withVar: true })
 *   }}
 * >
 *   Themed content
 * </div>
 * ```
 */
export function tokenToCssVar(token: string, options: TokenToCssVarOptions = {}): string {
  const { prefix = '', withVar = false } = options;

  // Validate input
  if (typeof token !== 'string' || token.trim() === '') {
    console.warn('[tokenToCssVar] Token must be a non-empty string');
    return '';
  }

  // Convert dot notation to kebab-case
  let varName = token
    .trim()
    .split('.')
    .map((part) => part.toLowerCase())
    .join('-');

  // Add prefix if provided
  if (prefix) {
    varName = `${prefix.toLowerCase()}-${varName}`;
  }

  // Add CSS variable prefix
  varName = `--${varName}`;

  // Wrap in var() if requested
  if (withVar) {
    return `var(${varName})`;
  }

  return varName;
}
